/**
 * Extract text from the first page of a PDF and save it to an Excel file.
 *
 * Usage:  node scripts/pdf_to_excel.js <input.pdf> [output.xlsx]
 *
 * Defaults:
 *   input  → testbed/docs/handbook.pdf
 *   output → output/first_page.xlsx
 */

const fs = require("fs");
const path = require("path");
const pdfParse = require("pdf-parse");
const ExcelJS = require("exceljs");

async function extractFirstPage(pdfPath) {
  const buffer = fs.readFileSync(pdfPath);

  // pdf-parse option: limit to first page only
  const data = await pdfParse(buffer, { max: 1 });
  return data.text.trim();
}

async function saveToExcel(text, outputPath) {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet("Page 1");

  // Header row
  sheet.columns = [
    { header: "Line #", key: "line", width: 10 },
    { header: "Text", key: "text", width: 100 },
  ];

  // Bold header
  sheet.getRow(1).font = { bold: true };

  // One row per line of extracted text
  const lines = text.split(/\r?\n/);
  lines.forEach((line, i) => {
    sheet.addRow({ line: i + 1, text: line });
  });

  // Ensure output directory exists
  fs.mkdirSync(path.dirname(outputPath), { recursive: true });

  await workbook.xlsx.writeFile(outputPath);
  return lines.length;
}

(async () => {
  const pdfPath = process.argv[2] || path.join(__dirname, "..", "testbed", "docs", "handbook.pdf");
  const xlsxPath = process.argv[3] || path.join(__dirname, "..", "output", "first_page.xlsx");

  console.log(`📄 Reading PDF : ${pdfPath}`);
  const text = await extractFirstPage(pdfPath);

  console.log(`\n--- Extracted text (first page) ---\n${text}\n----------------------------------`);

  const rowCount = await saveToExcel(text, xlsxPath);
  console.log(`\n✅ Saved ${rowCount} lines to: ${xlsxPath}`);
})();

