/**
 * Extract text from the first page of a PDF and save it to an Excel file.
 *
 * Usage:  node scripts/pdf_to_excel.js <input.pdf> [output.xlsx]
 *
 * Defaults:
 *   input  → testbed/docs/handbook.pdf
 *   output → output/first_page.xlsx
 */

const fs = require("fs");
const path = require("path");
const ExcelJS = require("exceljs");

async function extractFirstPage(pdfPath) {
  // pdf-parse has a non-standard export; use dynamic import as fallback
  let pdfParse;
  try {
    const mod = require("pdf-parse");
    pdfParse = typeof mod === "function" ? mod : mod.default || mod.PDFParse;
  } catch {
    pdfParse = null;
  }

  const buffer = fs.readFileSync(pdfPath);

  if (typeof pdfParse === "function" && pdfParse.prototype) {
    // Class-based API (e.g., PDFParse)
    const parser = new pdfParse(pdfPath);
    await parser.parse();
    const methods = Object.getOwnPropertyNames(Object.getPrototypeOf(parser))
      .filter((m) => m !== "constructor");
    console.log("PDFParse methods:", methods);
    return "";
  }

  if (typeof pdfParse === "function") {
    // Traditional function-based API
    const data = await pdfParse(buffer, { max: 1 });
    return data.text.trim();
  }

  // Fallback: use PDFParse class
  const { PDFParse: PDFParseClass } = require("pdf-parse");
  const parser = new PDFParseClass(pdfPath);
  await parser.parse();
  // Try to get text
  if (typeof parser.getText === "function") return parser.getText();
  if (typeof parser.getRawTextContent === "function") return parser.getRawTextContent();
  // Explore the object
  console.log("Parser keys:", Object.keys(parser));
  const methods = Object.getOwnPropertyNames(Object.getPrototypeOf(parser))
    .filter((m) => m !== "constructor");
  console.log("Parser methods:", methods);
  return "";
}

