/**
 * Extract text from the first page of a PDF and save it to an Excel file.
 *
 * Usage:  node scripts/pdf_to_excel.js [input.pdf] [output.xlsx]
 *
 * Defaults:
 *   input  → testbed/docs/handbook.pdf
 *   output → output/first_page.xlsx
 */

const fs = require("fs");
const path = require("path");
const ExcelJS = require("exceljs");

async function extractFirstPage(pdfPath) {
  // Use pdfjs-dist (the official Mozilla PDF.js library)
  const pdfjsLib = require("pdfjs-dist/legacy/build/pdf.mjs");

  const data = new Uint8Array(fs.readFileSync(pdfPath));
  const doc = await pdfjsLib.getDocument({ data }).promise;

  const page = await doc.getPage(1); // first page (1-indexed)
  const content = await page.getTextContent();

  // Concatenate text items, inserting newlines where vertical position changes
  let text = "";
  let lastY = null;
  for (const item of content.items) {
    if (item.str === undefined) continue;
    const y = item.transform ? item.transform[5] : null;
    if (lastY !== null && y !== null && Math.abs(y - lastY) > 2) {
      text += "\n";
    } else if (text.length > 0 && lastY === y) {
      text += " ";
    }
    text += item.str;
    lastY = y;
  }

  await doc.destroy();
  return text.trim();
}

async function saveToExcel(text, outputPath) {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet("Page 1");

  sheet.columns = [
    { header: "Line #", key: "line", width: 10 },
    { header: "Text", key: "text", width: 100 },
  ];

  // Bold header
  sheet.getRow(1).font = { bold: true };

  const lines = text.split(/\r?\n/);
  lines.forEach((line, i) => {
    sheet.addRow({ line: i + 1, text: line });
  });

  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  await workbook.xlsx.writeFile(outputPath);
  return lines.length;
}

(async () => {
  const pdfPath =
    process.argv[2] ||
    path.join(__dirname, "..", "testbed", "docs", "handbook.pdf");
  const xlsxPath =
    process.argv[3] ||
    path.join(__dirname, "..", "output", "first_page.xlsx");

  console.log(`📄 Reading PDF: ${pdfPath}`);
  const text = await extractFirstPage(pdfPath);

  console.log(`\n--- Extracted text (first page) ---`);
  console.log(text.slice(0, 2000));
  if (text.length > 2000) console.log(`... (${text.length} chars total)`);
  console.log(`--- end ---`);

  const rowCount = await saveToExcel(text, xlsxPath);
  console.log(`\n✅ Saved ${rowCount} lines to: ${xlsxPath}`);
})();

